import { CHANGE_PAGE } from "../actions/types";
const initialState = {
  page: "ProcessGroups"
};

export default function(state = initialState, action) {
  switch (action.type) {
    case CHANGE_PAGE:
      return {
        page: action.payload.page
      };
    default: {
      return state;
    }
  }
}
